import sys

def min_bribe_cost(n, a):
    # Convert input list to a dictionary for easier access
    boxer_strength_to_cost = {strength + 1: cost for strength, cost in enumerate(a)}

    # Find your friend's strength
    friend_strength = boxer_strength_to_cost[-1]

    # Function to simulate the tournament and calculate the total bribe cost
    def simulate_tournament(boxer_strength_to_cost, friend_strength):
        total_cost = 0
        while len(boxer_strength_to_cost) > 1:
            new_boxer_strength_to_cost = {}
            for i in range(1, len(boxer_strength_to_cost), 2):
                boxer1 = sorted(boxer_strength_to_cost.keys())[i - 1]
                boxer2 = sorted(boxer_strength_to_cost.keys())[i]
                if boxer1 == friend_strength or boxer2 == friend_strength:
                    winner = max(boxer1, boxer2)
                    total_cost += boxer_strength_to_cost[winner] if winner != friend_strength else 0
                else:
                    winner = min(boxer1, boxer2)
                new_boxer_strength_to_cost[winner] = min(boxer_strength_to_cost[boxer1], boxer_strength_to_cost[boxer2])
            boxer_strength_to_cost = new_boxer_strength_to_cost
        return total_cost

    return simulate_tournament(boxer_strength_to_cost, friend_strength)

