def min_bribe_to_win_tournament(n, costs):
    friends_strength = [i+1 for i, cost in enumerate(costs) if cost == -1][0]

    def binary_search(start, end):
        if start >= end:
            return float('inf')

        mid = (start + end) // 2
        left_cost = sum(max(0, costs[i] - costs[mid]) for i in range(mid) if i != friends_strength - 1)
        right_cost = sum(max(0, costs[i] - costs[mid]) for i in range(mid + 1, n) if i != friends_strength - 1)

        return min(left_cost, right_cost) + binary_search(mid + 1, end)

    return min(binary_search(0, n // 2), binary_search(n // 2, n))

